import { LOCATIONS, getNodeDisplayInfoByLocid } from "@/app/locations-server";

export interface GraphNode {
  id: number;
  coordinates?: { floor: string };
}

export interface GraphEdge {
  from: number;
  to: number;
  distance: number;
  outdoor?: boolean; // true if this edge is outdoors (penalty in rainy mode)
  hasStairs?: boolean; // true if vertical movement via stairs (penalty in barrier-free mode)
  notice?: {
    text: string;
  };
}

export interface NodeTriplet {
  previous: number | null;
  current: number;
  next: number | null;
  prev_name: string | null;
  curr_name: string;
  next_name: string | null;
  image: string;
}

// 屋外ナビゲーション用のSVG座標とノードIDのマッピング
// 建物地図用の現在地マーカー定義
export interface BuildingFloorMarker {
  id: string; // ユニークなID
  nodeId: number; // 対応するノード番号
  cx: number; // SVG座標 X
  cy: number; // SVG座標 Y
  label: string; // 表示用ラベル
  description: string; // 詳細説明
}

export interface BuildingFloorMap {
  buildingId: string; // 建物ID
  buildingName: string; // 建物名
  floors: Array<{
    floorId: string; // フロアID (例: "B1F", "1F", "2F")
    floorName: string; // フロア表示名 (例: "B1階", "1階", "2階")
    mapImageUrl: string; // フロアマップSVGのURL
    markers: BuildingFloorMarker[]; // このフロアの現在地マーカー
  }>;
}

