/**
 * Barrier-free edge set (accessible routes only)
 * For now, uses all edges from GRAPH_EDGES with penalties applied separately
 */
const GRAPH_EDGES_BARRIER_FREE: GraphEdge[] = GRAPH_EDGES;

/**
 * Edge selection function based on route conditions
 * Priority: barrierFree > rainy > normal
 *
 * Penalty strategy:
 * - Rainy mode: multiply outdoor edge distances by 100 (prefer indoors)
 * - Barrier-free mode: multiply stair edge distances by 100 (prefer elevators)
 */
export type EdgeParams = { rainy?: boolean; barrierFree?: boolean };

const RAINY_OUTDOOR_PENALTY = 100;
const BARRIER_FREE_STAIRS_PENALTY = 100;

export function getEdges(params: EdgeParams = {}): GraphEdge[] {
  const { rainy = false, barrierFree = false } = params;

  let edges = GRAPH_EDGES;

  // Apply barrier-free penalties (stairs): priority order
  if (barrierFree) {
    edges = edges.map((edge) => {
      if ("hasStairs" in edge && edge.hasStairs) {
        // Penalize stairs heavily to force elevator preference
        return {
          ...edge,
          distance: edge.distance * BARRIER_FREE_STAIRS_PENALTY,
        };
      }
      return edge;
    });
  }

  // Apply rainy mode penalties (outdoor)
  if (rainy) {
    edges = edges.map((edge) => {
      if (edge.outdoor) {
        // Penalize outdoor paths heavily to force indoor preference
        return { ...edge, distance: edge.distance * RAINY_OUTDOOR_PENALTY };
      }
      return edge;
    });
  }

  return edges;
}

