// Dijkstra's algorithm for shortest path
function dijkstra(
  nodes: GraphNode[],
  edges: GraphEdge[],
  start: number,
  end: number,
  excludedEdges: Array<{ from: number; to: number }> = [],
): number[] {
  const distances: { [key: number]: number } = {};
  const previous: { [key: number]: number | null } = {};
  const unvisited = new Set<number>();

  // 探索対象ノードは、固定ノード配列だけでなくエッジに現れる全ノードを含める
  // （屋外ノード 201+ なども探索できるようにする）
  const nodeIds = new Set<number>(nodes.map((node) => node.id));
  edges.forEach((edge) => {
    nodeIds.add(edge.from);
    nodeIds.add(edge.to);
  });
  nodeIds.add(start);
  nodeIds.add(end);

  // Initialize distances
  nodeIds.forEach((nodeId) => {
    distances[nodeId] = nodeId === start ? 0 : Number.POSITIVE_INFINITY;
    previous[nodeId] = null;
    unvisited.add(nodeId);
  });

  while (unvisited.size > 0) {
    // Find unvisited node with minimum distance
    const current = Array.from(unvisited).reduce((min, node) =>
      distances[node] < distances[min] ? node : min,
    );

    if (distances[current] === Number.POSITIVE_INFINITY) break;
    if (current === end) break;

    unvisited.delete(current);

    // Check neighbors
    const availableEdges = edges.filter((edge) => {
      const isExcluded = excludedEdges.some(
        (ex) => ex.from === edge.from && ex.to === edge.to,
      );

      return !isExcluded && edge.from === current;
    });

    availableEdges.forEach((edge) => {
      const neighbor = edge.to;
      if (!unvisited.has(neighbor)) return;
      // NOTE: Previously, nodes with id >= 100 were skipped here as "special nodes".
      // That restriction has been removed so that nodes >= 100 can be used as
      // intermediate nodes (necessary when many intersections are numbered >100).
      // If you want to reintroduce a restriction, modify this logic accordingly.

      const alt = distances[current] + edge.distance;
      if (alt < distances[neighbor]) {
        distances[neighbor] = alt;
        previous[neighbor] = current;
      }
    });
  }

  // Reconstruct path
  const path: number[] = [];
  let current: number | null = end;

  while (current !== null) {
    path.unshift(current);
    current = previous[current];
  }

  return path[0] === start ? path : [];
}

export function getNodeTriplet(
  previous: number | null,
  current: number,
  next: number | null,
): NodeTriplet {
  const triplet = NODE_TRIPLETS.find(
    (t) => t.previous === previous && t.current === current && t.next === next,
  );

  if (!triplet) {
    throw new Error(
      `No triplet definition found for (${previous}, ${current}, ${next})`,
    );
  }

  return triplet;
}

export function getEdgeInfo(from: number, to: number): GraphEdge | null {
  return (
    GRAPH_EDGES.find((edge) => edge.from === from && edge.to === to) || null
  );
}

export async function findRoute(
  departure: number,
  destination: number,
  excludedEdges: Array<{ from: number; to: number }> = [],
  rainyMode = false,
  barrierFreeMode = false,
) {
  // console.log(
  //   `Finding route from ${departure} to ${destination} (rainyMode: ${rainyMode}, barrierFreeMode: ${barrierFreeMode})`
  // );

  const departureLoc = parseInt(
    LOCATIONS.find((loc) => loc.id === departure.toString())?.locid ??
      departure.toString(),
  );
  const destinationLoc = parseInt(
    LOCATIONS.find((loc) => loc.id === destination.toString())?.locid ??
      destination.toString(),
  );

  if (destinationLoc === 169) {
    rainyMode = false;
  }

  // Use getEdges function to select appropriate edge set
  const edgeSet = getEdges({ rainy: rainyMode, barrierFree: barrierFreeMode });

  const path = dijkstra(
    GRAPH_NODES,
    edgeSet,
    departureLoc,
    destinationLoc,
    excludedEdges,
  );

  if (path.length === 0) {
    throw new Error(`No route found from ${departureLoc} to ${destinationLoc}`);
  }

  const route = [];
  const buildStartStep = (
    fallbackLocid: number,
    rawHeadline: string | null,
  ) => {
    if (rawHeadline && rawHeadline.trim() !== "") {
      return { title: rawHeadline, subtitle: undefined };
    }

    const displayInfo = getNodeDisplayInfoByLocid(fallbackLocid.toString());

    if (displayInfo?.name && displayInfo.name.trim() !== "") {
      return { title: "出発", subtitle: displayInfo.name };
    }

    if (displayInfo?.position && displayInfo.position.trim() !== "") {
      return { title: "出発", subtitle: displayInfo.position };
    }

    return { title: "出発", subtitle: "ここ" };
  };

  // console.log("Path found:", path);

  // 2ノードパス（出発地と目的地が直結）の特別処理
  // 通常のtripletループはprevious/nextが undefined になりトリプレット検索が失敗するため
  if (path.length === 2) {
    const [depNode, destNode] = path;
    const startStep = buildStartStep(departureLoc, null);

    // current=depNode, next=destNode に一致するトリプレットを探す（previousは問わない）
    const directTriplet =
      NODE_TRIPLETS.find((t) => t.current === depNode && t.next === destNode) ??
      null;

    route.push({
      id: depNode.toString(),
      title: startStep.title,
      subtitle: startStep.subtitle,
      image: directTriplet?.image || "/placeholder.svg?height=400&width=400",
      notice: undefined,
    });
    route.push({
      id: destNode.toString(),
      title:
        directTriplet?.curr_name ||
        getNodeDisplayInfoByLocid(destinationLoc.toString())?.name ||
        "目的地",
      subtitle: undefined,
      image: directTriplet?.image || "/placeholder.svg?height=400&width=400",
      notice: getEdgeInfo(depNode, destNode)?.notice ?? undefined,
    });
  } else {
    for (let i = 0; i < path.length; i++) {
      const isStart = i === 0;
      const isEnd = i === path.length - 1;

      const previous = isStart ? path[i] : isEnd ? path[i - 2] : path[i - 1];
      const current = isStart ? path[i + 1] : isEnd ? path[i - 1] : path[i];
      const next = isStart ? path[i + 2] : isEnd ? path[i] : path[i + 1];

      try {
        const triplet = getNodeTriplet(previous, current, next);
        const edgeInfo = isEnd ? null : getEdgeInfo(current, next);
        const startStep = isStart
          ? buildStartStep(departureLoc, triplet.prev_name)
          : null;

        const headline = isStart
          ? startStep?.title
          : isEnd
            ? triplet.next_name
            : triplet.curr_name;

        route.push({
          id: current.toString(),
          title: headline,
          subtitle: startStep?.subtitle,
          image: triplet.image || "/placeholder.svg?height=400&width=400",
          // connector:
          //   edgeInfo?.notice?.text ||
          // (next ? `Continue to next location` : undefined),
          notice: edgeInfo?.notice,
        });
      } catch (error) {
        console.error(
          `Error getting triplet for (${previous}, ${current}, ${next}):`,
          error,
        );
        throw error;

        // route.push({
        //   id: current.toString(),
        //   title: current.toString,
        //   description: "triplet.description",
        //   image: "placeholder.svg?height=400&width=400",
        //   connector: "Continue to next location",
        //   notice: null,
        // });
      }
    }
  } // end of path.length > 2 branch

  const cost = path.slice(0, -1).reduce((sum, node, i) => {
    const edge = getEdgeInfo(node, path[i + 1]);
    return sum + (edge ? edge.distance : 0);
  }, 0);

  return {
    nodes: path,
    edges: path
      .slice(0, -1)
      .map((node, i) => ({ from: node, to: path[i + 1] })),
    route,
    cost,
  };
}
